import { readFile, writeFile } from 'node:fs/promises';

export async function reshape(path, map) {
  const raw = JSON.parse(await readFile(path, 'utf8'));
  const next = map(raw);
  await writeFile(path, `${JSON.stringify(next, null, 2)}\n`);
  return next;
}

export function applySyntaxByLanguage(language: string, html: string): string {
  const alias = normalizeLanguageAlias(language) ?? language;
  return transformers[alias]?.(html) ?? html;
}

export function toErrorSnapshot(error: unknown) {
  if (error instanceof Error) {
    return { name: error.name, message: error.message };
  }
  return { name: 'UnknownError', message: String(error) };
}
